2. 创建权限校验装饰器:
def permission_required(permission):
    def wrapper(fn):
        @wraps(fn)
        def decorator(*args, **kwargs):
            current_permissions =
get_jwt_claims().get("permissions", [])
            if permission not in current_permissions:
                abort(403)
            return fn(*args, **kwargs)
        return decorator
    return wrapper
